import { test, expect } from '@playwright/test';

test.describe('Login Page Mobile Display', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/login');
    await page.setViewportSize({ width: 375, height: 812 }); // iPhone X dimensions
  });

  test('should display the login form correctly', async ({ page }) => {
    const loginForm = page.getByRole('form', { name: /login/i });
    await expect(loginForm).toBeVisible();
    await expect(loginForm).toHaveCSS('max-width', '100%');
  });

  test('should have a visible username and password field', async ({ page }) => {
    const usernameField = page.getByLabel('Username');
    const passwordField = page.getByLabel('Password');

    await expect(usernameField).toBeVisible();
    await expect(passwordField).toBeVisible();
  });
});
